CREATE DATABASE IF NOT EXISTS villagecraft CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE villagecraft;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255), role ENUM('CUSTOMER','PRODUCER','ADMIN') NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE oauth_accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, provider ENUM('GOOGLE','FACEBOOK') NOT NULL, provider_subject VARCHAR(190) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,provider_subject), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE producer_profiles (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL UNIQUE, village VARCHAR(120), district VARCHAR(120), phone VARCHAR(40), payout_reference VARCHAR(190), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE product_submissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, producer_id BIGINT NOT NULL, name VARCHAR(180) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT NOT NULL, proposed_wholesale_price DECIMAL(12,2) NOT NULL, image_url VARCHAR(500), status ENUM('SUBMITTED','UNDER_REVIEW','CHANGES_REQUESTED','APPROVED','REJECTED') NOT NULL DEFAULT 'SUBMITTED', reviewed_by BIGINT, review_notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(producer_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT, submission_id BIGINT, sku VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT NOT NULL, retail_price DECIMAL(12,2) NOT NULL, status ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(submission_id) REFERENCES product_submissions(id));
CREATE TABLE product_images (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, image_url VARCHAR(500) NOT NULL, alt_text VARCHAR(200), sort_order INT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE purchase_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, submission_id BIGINT NOT NULL, quantity INT NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, status ENUM('CREATED','IN_TRANSIT','RECEIVED','CANCELLED') NOT NULL DEFAULT 'CREATED', expected_at DATE, received_at DATE, created_by BIGINT NOT NULL, FOREIGN KEY(submission_id) REFERENCES product_submissions(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE value_addition_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, activity ENUM('BRANDING','PACKAGING','FINISHING','TRANSPORT','OTHER') NOT NULL, description VARCHAR(500) NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, quantity INT NOT NULL DEFAULT 1, recorded_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE inventory (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL UNIQUE, quantity_on_hand INT NOT NULL DEFAULT 0, quantity_reserved INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(quantity_on_hand >= 0), CHECK(quantity_reserved >= 0), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE customer_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_number VARCHAR(40) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, subtotal DECIMAL(12,2) NOT NULL, delivery_address TEXT NOT NULL, status ENUM('PENDING_PAYMENT','PAYMENT_REVIEW','PAID','PROCESSING','SHIPPED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING_PAYMENT', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES customer_orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, method ENUM('BANK_TRANSFER','CASH_ON_DELIVERY','SIMULATED_GATEWAY') NOT NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('PENDING','SIMULATED_SUCCESS','SLIP_UPLOADED','VERIFIED','REJECTED','FAILED') NOT NULL DEFAULT 'PENDING', provider_reference VARCHAR(190), bank_slip_url VARCHAR(500), verified_by BIGINT, verified_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES customer_orders(id), FOREIGN KEY(verified_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_user_id BIGINT, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80), details JSON, ip_address VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE INDEX idx_submission_producer_status ON product_submissions(producer_id,status);
CREATE INDEX idx_orders_customer_date ON customer_orders(customer_id,created_at);
CREATE INDEX idx_payments_status ON payments(status);
